// with the token in "meta"; 401 while a code is pending, with the session
// token to carry; 400 with "errors"; 409 once the pending code is gone. A
CloudSignInOutcome CloudSignIn::failed(const std::string& code, const std::string& message, bool retryable)
{
    m_phase = CloudSignInPhase::Idle;
    m_token.clear();
    CloudSignInOutcome outcome;
    outcome.kind  = CloudSignInOutcome::Kind::Failed;
    outcome.error = AgentError{code, message, retryable};
    return outcome;
}

std::string CloudSignIn::link_url(const std::string& link) const
{
    // JusPrin's own Terms and Privacy Policy: JusPrin accounts are separate
    // from Obico's. The pages have no site menu leading on to Obico's.
    if (link == "terms")
        return "https://www.obico.io/jusprin-terms.html";
    if (link == "privacy")
        return "https://www.obico.io/jusprin-privacy.html";
    if (link == "reset_password")
        return m_server + "/accounts/password/reset/";
    return {};
}

